"use strict";(globalThis.webpackChunktextbook=globalThis.webpackChunktextbook||[]).push([[7327],{8453:(e,n,r)=>{r.d(n,{R:()=>o,x:()=>s});var t=r(6540);const i={},a=t.createContext(i);function o(e){const n=t.useContext(a);return t.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function s(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:o(e.components),t.createElement(a.Provider,{value:n},e.children)}},9394:(e,n,r)=>{r.r(n),r.d(n,{assets:()=>l,contentTitle:()=>s,default:()=>m,frontMatter:()=>o,metadata:()=>t,toc:()=>c});const t=JSON.parse('{"id":"chapter-5/submodule-1-foundation-models","title":"Submodule 1: Foundation Models","description":"Introduction to Vision-Language Foundation Models","source":"@site/docs/chapter-5/submodule-1-foundation-models.md","sourceDirName":"chapter-5","slug":"/chapter-5/submodule-1-foundation-models","permalink":"/humanoid-robotics-textbook/docs/chapter-5/submodule-1-foundation-models","draft":false,"unlisted":false,"editUrl":"https://github.com/aidd-projects/humanoid-robotics-textbook/tree/main/docs/chapter-5/submodule-1-foundation-models.md","tags":[],"version":"current","sidebarPosition":27,"frontMatter":{"sidebar_position":27,"title":"Submodule 1: Foundation Models"},"sidebar":"tutorialSidebar","previous":{"title":"Chapter 5: VLA: Vision-Language-Action Robotics","permalink":"/humanoid-robotics-textbook/docs/chapter-5/"},"next":{"title":"Submodule 2: Action Spaces","permalink":"/humanoid-robotics-textbook/docs/chapter-5/submodule-2-action-spaces"}}');var i=r(4848),a=r(8453);const o={sidebar_position:27,title:"Submodule 1: Foundation Models"},s="Submodule 1: Foundation Models",l={},c=[{value:"Introduction to Vision-Language Foundation Models",id:"introduction-to-vision-language-foundation-models",level:2},{value:"Architecture of Vision-Language Models",id:"architecture-of-vision-language-models",level:2},{value:"CLIP: Contrastive Language-Image Pretraining",id:"clip-contrastive-language-image-pretraining",level:3},{value:"BLIP: Bootstrapping Language-Image Pretraining",id:"blip-bootstrapping-language-image-pretraining",level:3},{value:"Flamingo: Few-Shot Learning for Vision-Language Tasks",id:"flamingo-few-shot-learning-for-vision-language-tasks",level:3},{value:"Vision-Language Models for Robotics",id:"vision-language-models-for-robotics",level:2},{value:"Robot Operating System (ROS) Integration",id:"robot-operating-system-ros-integration",level:3},{value:"Training Vision-Language Models",id:"training-vision-language-models",level:2},{value:"Contrastive Learning Approach",id:"contrastive-learning-approach",level:3},{value:"Dataset Preparation",id:"dataset-preparation",level:3},{value:"Advanced Vision-Language Architectures",id:"advanced-vision-language-architectures",level:2},{value:"Vision-Language-Action Integration",id:"vision-language-action-integration",level:3},{value:"Evaluation Metrics for Vision-Language Models",id:"evaluation-metrics-for-vision-language-models",level:2},{value:"Zero-Shot Classification Accuracy",id:"zero-shot-classification-accuracy",level:3},{value:"Practical Considerations for Robotics",id:"practical-considerations-for-robotics",level:2},{value:"Real-Time Inference Optimization",id:"real-time-inference-optimization",level:3},{value:"Challenges and Limitations",id:"challenges-and-limitations",level:2},{value:"Domain Gap Issues",id:"domain-gap-issues",level:3},{value:"Summary",id:"summary",level:2},{value:"Key Takeaways",id:"key-takeaways",level:2}];function d(e){const n={code:"code",h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,a.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"submodule-1-foundation-models",children:"Submodule 1: Foundation Models"})}),"\n",(0,i.jsx)(n.h2,{id:"introduction-to-vision-language-foundation-models",children:"Introduction to Vision-Language Foundation Models"}),"\n",(0,i.jsx)(n.p,{children:"Vision-Language (VL) foundation models represent a breakthrough in artificial intelligence, combining visual perception and natural language understanding in unified neural architectures. These models, trained on massive datasets of image-text pairs, form the backbone of modern Vision-Language-Action (VLA) robotic systems by enabling robots to interpret human instructions and perceive their environment in a semantically meaningful way."}),"\n",(0,i.jsx)(n.p,{children:"The emergence of foundation models has transformed robotics from task-specific programming to generalizable instruction-following capabilities. These models learn rich representations of the visual world grounded in language, enabling robots to understand complex commands and adapt to novel situations without explicit programming."}),"\n",(0,i.jsx)(n.h2,{id:"architecture-of-vision-language-models",children:"Architecture of Vision-Language Models"}),"\n",(0,i.jsx)(n.h3,{id:"clip-contrastive-language-image-pretraining",children:"CLIP: Contrastive Language-Image Pretraining"}),"\n",(0,i.jsx)(n.p,{children:"CLIP (Contrastive Language-Image Pre-training) was one of the first successful approaches to learning visual representations through natural language supervision. The model consists of two encoders:"}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Image Encoder"}),": Processes visual input to create image embeddings\r\n",(0,i.jsx)(n.strong,{children:"Text Encoder"}),": Processes textual descriptions to create text embeddings"]}),"\n",(0,i.jsx)(n.p,{children:"Both encoders map their inputs to a shared embedding space where image and text representations can be directly compared through cosine similarity."}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-python",children:'import torch\r\nimport torch.nn as nn\r\nimport torchvision.transforms as transforms\r\nfrom transformers import CLIPProcessor, CLIPModel\r\n\r\nclass CLIPVisionLanguageModel(nn.Module):\r\n    def __init__(self, model_name="openai/clip-vit-base-patch32"):\r\n        super().__init__()\r\n        self.clip_model = CLIPModel.from_pretrained(model_name)\r\n        self.processor = CLIPProcessor.from_pretrained(model_name)\r\n\r\n    def encode_image(self, images):\r\n        """Encode images to embeddings"""\r\n        image_features = self.clip_model.get_image_features(pixel_values=images)\r\n        # Normalize embeddings\r\n        image_features = image_features / image_features.norm(dim=-1, keepdim=True)\r\n        return image_features\r\n\r\n    def encode_text(self, texts):\r\n        """Encode text to embeddings"""\r\n        text_inputs = self.processor(text=texts, return_tensors="pt", padding=True)\r\n        text_features = self.clip_model.get_text_features(**text_inputs)\r\n        # Normalize embeddings\r\n        text_features = text_features / text_features.norm(dim=-1, keepdim=True)\r\n        return text_features\r\n\r\n    def similarity(self, images, texts):\r\n        """Compute similarity between images and texts"""\r\n        image_features = self.encode_image(images)\r\n        text_features = self.encode_text(texts)\r\n\r\n        # Compute cosine similarity\r\n        similarity = torch.matmul(image_features, text_features.t())\r\n        return similarity\n'})}),"\n",(0,i.jsx)(n.h3,{id:"blip-bootstrapping-language-image-pretraining",children:"BLIP: Bootstrapping Language-Image Pretraining"}),"\n",(0,i.jsx)(n.p,{children:"BLIP extends the vision-language paradigm by introducing a unified framework that jointly learns vision and language representations. It uses a bootstrapping approach where synthetic captions help improve the model's understanding."}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-python",children:'from transformers import BlipProcessor, BlipForConditionalGeneration\r\n\r\nclass BLIPModel(nn.Module):\r\n    def __init__(self, model_name="Salesforce/blip-image-captioning-base"):\r\n        super().__init__()\r\n        self.processor = BlipProcessor.from_pretrained(model_name)\r\n        self.model = BlipForConditionalGeneration.from_pretrained(model_name)\r\n\r\n    def generate_caption(self, image):\r\n        """Generate caption for an image"""\r\n        inputs = self.processor(image, return_tensors="pt")\r\n\r\n        out = self.model.generate(**inputs)\r\n        caption = self.processor.decode(out[0], skip_special_tokens=True)\r\n        return caption\r\n\r\n    def encode_multimodal(self, image, text):\r\n        """Encode both image and text for multimodal understanding"""\r\n        inputs = self.processor(image, text, return_tensors="pt", padding=True)\r\n\r\n        outputs = self.model.text_encoder(**inputs)\r\n        return outputs.last_hidden_state\n'})}),"\n",(0,i.jsx)(n.h3,{id:"flamingo-few-shot-learning-for-vision-language-tasks",children:"Flamingo: Few-Shot Learning for Vision-Language Tasks"}),"\n",(0,i.jsx)(n.p,{children:"Flamingo models are designed for few-shot learning in vision-language tasks, making them particularly suitable for robotics applications where collecting large amounts of task-specific data is challenging."}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-python",children:'import torch\r\nfrom transformers import AutoProcessor, AutoModel\r\n\r\nclass FlamingoRobotModel(nn.Module):\r\n    def __init__(self, model_name="path/to/flamingo/model"):\r\n        super().__init__()\r\n        self.processor = AutoProcessor.from_pretrained(model_name)\r\n        self.model = AutoModel.from_pretrained(model_name)\r\n\r\n    def forward(self, images, texts, task_description=""):\r\n        """Process images and texts for robotic tasks"""\r\n        # Prepare inputs with task description\r\n        formatted_texts = [f"{task_description} {text}" for text in texts]\r\n\r\n        inputs = self.processor(\r\n            images=images,\r\n            text=formatted_texts,\r\n            return_tensors="pt",\r\n            padding=True\r\n        )\r\n\r\n        outputs = self.model(**inputs)\r\n        return outputs\n'})}),"\n",(0,i.jsx)(n.h2,{id:"vision-language-models-for-robotics",children:"Vision-Language Models for Robotics"}),"\n",(0,i.jsx)(n.h3,{id:"robot-operating-system-ros-integration",children:"Robot Operating System (ROS) Integration"}),"\n",(0,i.jsx)(n.p,{children:"Vision-language models can be integrated into ROS systems for real-time robotic applications:"}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-python",children:'import rclpy\r\nfrom rclpy.node import Node\r\nfrom sensor_msgs.msg import Image\r\nfrom std_msgs.msg import String\r\nfrom geometry_msgs.msg import Twist\r\nimport torch\r\nfrom transformers import CLIPProcessor, CLIPModel\r\nfrom cv_bridge import CvBridge\r\nimport cv2\r\n\r\nclass VisionLanguageRobotNode(Node):\r\n    def __init__(self):\r\n        super().__init__(\'vision_language_robot\')\r\n\r\n        # Initialize CLIP model\r\n        self.clip_model = CLIPModel.from_pretrained("openai/clip-vit-base-patch32")\r\n        self.clip_processor = CLIPProcessor.from_pretrained("openai/clip-vit-base-patch32")\r\n\r\n        # Initialize CV bridge\r\n        self.cv_bridge = CvBridge()\r\n\r\n        # Subscribers and publishers\r\n        self.image_sub = self.create_subscription(\r\n            Image, \'camera/image_raw\', self.image_callback, 10)\r\n        self.command_sub = self.create_subscription(\r\n            String, \'robot_command\', self.command_callback, 10)\r\n        self.velocity_pub = self.create_publisher(Twist, \'cmd_vel\', 10)\r\n\r\n        # Internal state\r\n        self.current_image = None\r\n        self.current_command = None\r\n\r\n        # Command classes for classification\r\n        self.command_classes = [\r\n            "move forward",\r\n            "turn left",\r\n            "turn right",\r\n            "stop",\r\n            "pick up object",\r\n            "place object",\r\n            "go to location"\r\n        ]\r\n\r\n    def image_callback(self, msg):\r\n        """Process incoming image data"""\r\n        try:\r\n            cv_image = self.cv_bridge.imgmsg_to_cv2(msg, "bgr8")\r\n            self.current_image = cv_image\r\n        except Exception as e:\r\n            self.get_logger().error(f"Error processing image: {e}")\r\n\r\n    def command_callback(self, msg):\r\n        """Process incoming command and execute action"""\r\n        self.current_command = msg.data\r\n\r\n        if self.current_image is not None:\r\n            self.execute_vision_language_command()\r\n\r\n    def execute_vision_language_command(self):\r\n        """Execute command using vision-language understanding"""\r\n        # Convert image to PIL format for CLIP\r\n        pil_image = cv2.cvtColor(self.current_image, cv2.COLOR_BGR2RGB)\r\n\r\n        # Process image and text with CLIP\r\n        inputs = self.clip_processor(\r\n            text=self.command_classes,\r\n            images=pil_image,\r\n            return_tensors="pt",\r\n            padding=True\r\n        )\r\n\r\n        outputs = self.clip_model(**inputs)\r\n        logits_per_image = outputs.logits_per_image\r\n        probs = logits_per_image.softmax(dim=-1)\r\n\r\n        # Get the most likely command\r\n        predicted_idx = probs.argmax().item()\r\n        predicted_command = self.command_classes[predicted_idx]\r\n        confidence = probs[0][predicted_idx].item()\r\n\r\n        # Execute action based on prediction\r\n        if confidence > 0.7:  # Confidence threshold\r\n            self.execute_robot_action(predicted_command)\r\n        else:\r\n            self.get_logger().info(f"Low confidence ({confidence:.2f}) for command: {predicted_command}")\r\n\r\n    def execute_robot_action(self, command):\r\n        """Execute robot action based on command"""\r\n        twist = Twist()\r\n\r\n        if command == "move forward":\r\n            twist.linear.x = 0.5\r\n        elif command == "turn left":\r\n            twist.angular.z = 0.5\r\n        elif command == "turn right":\r\n            twist.angular.z = -0.5\r\n        elif command == "stop":\r\n            pass  # Twist is already zero\r\n        # Add more commands as needed\r\n\r\n        self.velocity_pub.publish(twist)\r\n        self.get_logger().info(f"Executing command: {command}")\n'})}),"\n",(0,i.jsx)(n.h2,{id:"training-vision-language-models",children:"Training Vision-Language Models"}),"\n",(0,i.jsx)(n.h3,{id:"contrastive-learning-approach",children:"Contrastive Learning Approach"}),"\n",(0,i.jsx)(n.p,{children:"Vision-language models are typically trained using contrastive learning, where the model learns to match corresponding image-text pairs while distinguishing them from non-matching pairs."}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-python",children:'import torch\r\nimport torch.nn as nn\r\nimport torch.nn.functional as F\r\n\r\nclass VisionLanguageContrastiveLoss(nn.Module):\r\n    def __init__(self, temperature=0.07):\r\n        super().__init__()\r\n        self.temperature = temperature\r\n\r\n    def forward(self, image_features, text_features):\r\n        """\r\n        Compute contrastive loss for vision-language alignment\r\n        image_features: (batch_size, feature_dim)\r\n        text_features: (batch_size, feature_dim)\r\n        """\r\n        # Normalize features\r\n        image_features = F.normalize(image_features, dim=-1)\r\n        text_features = F.normalize(text_features, dim=-1)\r\n\r\n        # Compute similarity matrix\r\n        similarity = torch.matmul(image_features, text_features.t()) / self.temperature\r\n\r\n        # Create labels (diagonal elements should be maximized)\r\n        batch_size = image_features.shape[0]\r\n        labels = torch.arange(batch_size).to(image_features.device)\r\n\r\n        # Compute cross-entropy loss\r\n        loss_i = F.cross_entropy(similarity, labels)\r\n        loss_t = F.cross_entropy(similarity.t(), labels)\r\n\r\n        # Return symmetric loss\r\n        return (loss_i + loss_t) / 2\r\n\r\nclass VisionLanguageTrainer:\r\n    def __init__(self, image_encoder, text_encoder, learning_rate=1e-4):\r\n        self.image_encoder = image_encoder\r\n        self.text_encoder = text_encoder\r\n        self.loss_fn = VisionLanguageContrastiveLoss()\r\n        self.optimizer = torch.optim.Adam(\r\n            list(image_encoder.parameters()) + list(text_encoder.parameters()),\r\n            lr=learning_rate\r\n        )\r\n\r\n    def train_step(self, images, texts):\r\n        """Single training step"""\r\n        self.optimizer.zero_grad()\r\n\r\n        # Encode images and texts\r\n        image_features = self.image_encoder(images)\r\n        text_features = self.text_encoder(texts)\r\n\r\n        # Compute loss\r\n        loss = self.loss_fn(image_features, text_features)\r\n\r\n        # Backward pass\r\n        loss.backward()\r\n        self.optimizer.step()\r\n\r\n        return loss.item()\n'})}),"\n",(0,i.jsx)(n.h3,{id:"dataset-preparation",children:"Dataset Preparation"}),"\n",(0,i.jsx)(n.p,{children:"Training vision-language models requires large-scale datasets of image-text pairs:"}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-python",children:'import torch\r\nfrom torch.utils.data import Dataset\r\nimport json\r\nfrom PIL import Image\r\nimport torchvision.transforms as transforms\r\n\r\nclass VisionLanguageDataset(Dataset):\r\n    def __init__(self, data_path, image_dir, transform=None):\r\n        """\r\n        Dataset for vision-language training\r\n        data_path: Path to JSON file with image-text pairs\r\n        image_dir: Directory containing images\r\n        transform: Image transformations\r\n        """\r\n        with open(data_path, \'r\') as f:\r\n            self.data = json.load(f)\r\n\r\n        self.image_dir = image_dir\r\n        self.transform = transform or transforms.Compose([\r\n            transforms.Resize((224, 224)),\r\n            transforms.ToTensor(),\r\n            transforms.Normalize(mean=[0.485, 0.456, 0.406],\r\n                               std=[0.229, 0.224, 0.225])\r\n        ])\r\n\r\n    def __len__(self):\r\n        return len(self.data)\r\n\r\n    def __getitem__(self, idx):\r\n        item = self.data[idx]\r\n        image_path = f"{self.image_dir}/{item[\'image\']}"\r\n        text = item[\'text\']\r\n\r\n        # Load and transform image\r\n        image = Image.open(image_path).convert(\'RGB\')\r\n        image = self.transform(image)\r\n\r\n        return {\r\n            \'image\': image,\r\n            \'text\': text\r\n        }\r\n\r\n# Example of creating a robotic vision-language dataset\r\ndef create_robotic_dataset():\r\n    """\r\n    Create a sample dataset for robotic vision-language tasks\r\n    This would typically be much larger in practice\r\n    """\r\n    robotic_data = [\r\n        {\r\n            "image": "robot_arm_picking_red_block.jpg",\r\n            "text": "The robot arm is picking up a red block"\r\n        },\r\n        {\r\n            "image": "robot_navigating_corridor.jpg",\r\n            "text": "The robot is navigating through a corridor"\r\n        },\r\n        {\r\n            "image": "human_gesturing_to_robot.jpg",\r\n            "text": "A human is gesturing to the robot to come here"\r\n        },\r\n        {\r\n            "image": "robot_assisting_person.jpg",\r\n            "text": "The robot is assisting a person with an object"\r\n        }\r\n    ]\r\n\r\n    with open(\'robotic_vision_language_data.json\', \'w\') as f:\r\n        json.dump(robotic_data, f)\n'})}),"\n",(0,i.jsx)(n.h2,{id:"advanced-vision-language-architectures",children:"Advanced Vision-Language Architectures"}),"\n",(0,i.jsx)(n.h3,{id:"vision-language-action-integration",children:"Vision-Language-Action Integration"}),"\n",(0,i.jsx)(n.p,{children:"For robotics applications, vision-language models are extended to include action prediction:"}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-python",children:'class VisionLanguageActionModel(nn.Module):\r\n    def __init__(self, vision_encoder, language_encoder, action_head, hidden_dim=512):\r\n        super().__init__()\r\n\r\n        self.vision_encoder = vision_encoder\r\n        self.language_encoder = language_encoder\r\n        self.action_head = action_head\r\n\r\n        # Fusion layer to combine vision and language features\r\n        self.fusion_layer = nn.Sequential(\r\n            nn.Linear(hidden_dim * 2, hidden_dim),\r\n            nn.ReLU(),\r\n            nn.Linear(hidden_dim, hidden_dim)\r\n        )\r\n\r\n        # Action prediction head\r\n        self.action_predictor = nn.Sequential(\r\n            nn.Linear(hidden_dim, hidden_dim),\r\n            nn.ReLU(),\r\n            nn.Dropout(0.1),\r\n            nn.Linear(hidden_dim, action_head.output_dim)\r\n        )\r\n\r\n    def forward(self, images, texts):\r\n        # Encode vision and language separately\r\n        vision_features = self.vision_encoder(images)\r\n        language_features = self.language_encoder(texts)\r\n\r\n        # Fuse vision and language features\r\n        fused_features = torch.cat([vision_features, language_features], dim=-1)\r\n        fused_features = self.fusion_layer(fused_features)\r\n\r\n        # Predict actions\r\n        action_logits = self.action_predictor(fused_features)\r\n\r\n        return action_logits\r\n\r\nclass RoboticVLA:\r\n    def __init__(self, model, robot_interface):\r\n        self.model = model\r\n        self.robot_interface = robot_interface\r\n\r\n    def execute_command(self, image, command_text):\r\n        """Execute a command using vision-language-action model"""\r\n        # Process with VLA model\r\n        action_logits = self.model(image.unsqueeze(0), [command_text])\r\n\r\n        # Convert logits to robot action\r\n        robot_action = self.process_action_logits(action_logits)\r\n\r\n        # Execute action on robot\r\n        self.robot_interface.execute_action(robot_action)\r\n\r\n    def process_action_logits(self, logits):\r\n        """Convert model outputs to robot actions"""\r\n        # Apply softmax to get action probabilities\r\n        action_probs = torch.softmax(logits, dim=-1)\r\n\r\n        # Get the most probable action\r\n        action_idx = torch.argmax(action_probs, dim=-1)\r\n\r\n        # Map to robot action space\r\n        robot_action = self.map_action_index_to_robot_command(action_idx.item())\r\n\r\n        return robot_action\r\n\r\n    def map_action_index_to_robot_command(self, action_idx):\r\n        """Map action index to specific robot command"""\r\n        action_space = [\r\n            "move_forward",\r\n            "turn_left",\r\n            "turn_right",\r\n            "stop",\r\n            "grasp_object",\r\n            "release_object",\r\n            "move_arm_up",\r\n            "move_arm_down"\r\n        ]\r\n\r\n        if action_idx < len(action_space):\r\n            return action_space[action_idx]\r\n        else:\r\n            return "stop"  # Default action\n'})}),"\n",(0,i.jsx)(n.h2,{id:"evaluation-metrics-for-vision-language-models",children:"Evaluation Metrics for Vision-Language Models"}),"\n",(0,i.jsx)(n.h3,{id:"zero-shot-classification-accuracy",children:"Zero-Shot Classification Accuracy"}),"\n",(0,i.jsx)(n.p,{children:"Vision-language models can be evaluated on zero-shot classification tasks:"}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-python",children:'def evaluate_zero_shot_classification(model, test_loader, class_names):\r\n    """\r\n    Evaluate vision-language model on zero-shot classification\r\n    """\r\n    model.eval()\r\n    correct = 0\r\n    total = 0\r\n\r\n    with torch.no_grad():\r\n        for batch in test_loader:\r\n            images = batch[\'image\']\r\n            labels = batch[\'label\']\r\n\r\n            # Encode images\r\n            image_features = model.encode_image(images)\r\n\r\n            # Encode class names\r\n            text_features = model.encode_text(class_names)\r\n\r\n            # Compute similarity\r\n            similarity = (image_features @ text_features.T)\r\n\r\n            # Get predictions\r\n            predictions = similarity.argmax(dim=-1)\r\n\r\n            # Compute accuracy\r\n            correct += (predictions == labels).sum().item()\r\n            total += labels.size(0)\r\n\r\n    accuracy = correct / total\r\n    return accuracy\r\n\r\ndef evaluate_retrieval_performance(model, test_data):\r\n    """\r\n    Evaluate vision-language retrieval performance\r\n    """\r\n    model.eval()\r\n    all_image_features = []\r\n    all_text_features = []\r\n\r\n    with torch.no_grad():\r\n        for item in test_data:\r\n            image = item[\'image\']\r\n            text = item[\'text\']\r\n\r\n            image_features = model.encode_image(image)\r\n            text_features = model.encode_text([text])\r\n\r\n            all_image_features.append(image_features)\r\n            all_text_features.append(text_features)\r\n\r\n    all_image_features = torch.cat(all_image_features)\r\n    all_text_features = torch.cat(all_text_features)\r\n\r\n    # Compute similarity matrix\r\n    similarity_matrix = all_image_features @ all_text_features.T\r\n\r\n    # Compute retrieval metrics\r\n    # Image-to-text retrieval\r\n    i2t_r1 = compute_recall_at_k(similarity_matrix, k=1)\r\n    i2t_r5 = compute_recall_at_k(similarity_matrix, k=5)\r\n\r\n    # Text-to-image retrieval\r\n    t2i_r1 = compute_recall_at_k(similarity_matrix.T, k=1)\r\n    t2i_r5 = compute_recall_at_k(similarity_matrix.T, k=5)\r\n\r\n    return {\r\n        \'i2t_r1\': i2t_r1,\r\n        \'i2t_r5\': i2t_r5,\r\n        \'t2i_r1\': t2i_r1,\r\n        \'t2i_r5\': t2i_r5\r\n    }\r\n\r\ndef compute_recall_at_k(similarity_matrix, k=1):\r\n    """Compute recall at k for retrieval tasks"""\r\n    batch_size = similarity_matrix.shape[0]\r\n\r\n    # For each image, find the top-k most similar texts\r\n    top_k_indices = torch.topk(similarity_matrix, k, dim=1).indices\r\n\r\n    # Check if the correct text is in the top-k\r\n    correct = 0\r\n    for i in range(batch_size):\r\n        if i in top_k_indices[i]:\r\n            correct += 1\r\n\r\n    return correct / batch_size\n'})}),"\n",(0,i.jsx)(n.h2,{id:"practical-considerations-for-robotics",children:"Practical Considerations for Robotics"}),"\n",(0,i.jsx)(n.h3,{id:"real-time-inference-optimization",children:"Real-Time Inference Optimization"}),"\n",(0,i.jsx)(n.p,{children:"Vision-language models need optimization for real-time robotic applications:"}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-python",children:'class OptimizedVisionLanguageModel:\r\n    def __init__(self, model, device=\'cuda\'):\r\n        self.model = model.to(device)\r\n        self.device = device\r\n\r\n        # Optimize model with TensorRT or similar\r\n        self.optimize_model()\r\n\r\n    def optimize_model(self):\r\n        """Optimize model for inference"""\r\n        # Example: Convert to TensorRT (requires TensorRT installation)\r\n        try:\r\n            import torch_tensorrt\r\n            self.model = torch_tensorrt.compile(\r\n                self.model,\r\n                inputs=[\r\n                    torch_tensorrt.Input(\r\n                        min_shape=[1, 3, 224, 224],\r\n                        opt_shape=[8, 3, 224, 224],\r\n                        max_shape=[16, 3, 224, 224]\r\n                    )\r\n                ],\r\n                enabled_precisions={torch.float16}\r\n            )\r\n        except ImportError:\r\n            print("TensorRT not available, using regular model")\r\n\r\n    def preprocess_input(self, image, text):\r\n        """Preprocess inputs for optimized inference"""\r\n        # Convert image to tensor and normalize\r\n        if isinstance(image, np.ndarray):\r\n            image = torch.from_numpy(image).permute(2, 0, 1).float() / 255.0\r\n\r\n        # Normalize image\r\n        imagenet_mean = torch.tensor([0.485, 0.456, 0.406]).view(3, 1, 1)\r\n        imagenet_std = torch.tensor([0.229, 0.224, 0.225]).view(3, 1, 1)\r\n        image = (image - imagenet_mean) / imagenet_std\r\n\r\n        # Add batch dimension\r\n        image = image.unsqueeze(0).to(self.device)\r\n\r\n        return image, text\r\n\r\n    def inference_with_timing(self, image, text):\r\n        """Run inference with timing measurements"""\r\n        import time\r\n\r\n        start_time = time.time()\r\n\r\n        # Preprocess\r\n        processed_image, processed_text = self.preprocess_input(image, text)\r\n\r\n        preprocess_time = time.time() - start_time\r\n\r\n        # Run model\r\n        with torch.no_grad():\r\n            if torch.cuda.is_available():\r\n                torch.cuda.synchronize()\r\n\r\n            inference_start = time.time()\r\n            output = self.model(processed_image, processed_text)\r\n\r\n            if torch.cuda.is_available():\r\n                torch.cuda.synchronize()\r\n\r\n            inference_time = time.time() - inference_start\r\n\r\n        total_time = time.time() - start_time\r\n\r\n        return {\r\n            \'output\': output,\r\n            \'preprocess_time\': preprocess_time,\r\n            \'inference_time\': inference_time,\r\n            \'total_time\': total_time\r\n        }\n'})}),"\n",(0,i.jsx)(n.h2,{id:"challenges-and-limitations",children:"Challenges and Limitations"}),"\n",(0,i.jsx)(n.h3,{id:"domain-gap-issues",children:"Domain Gap Issues"}),"\n",(0,i.jsx)(n.p,{children:"Vision-language models trained on internet-scale data may not generalize well to robotic environments:"}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-python",children:'class DomainAdaptationTrainer:\r\n    def __init__(self, base_model, source_dataset, target_dataset):\r\n        self.base_model = base_model\r\n        self.source_dataset = source_dataset  # Internet-scale data\r\n        self.target_dataset = target_dataset  # Robotic data\r\n\r\n    def adapt_to_robotic_domain(self, num_epochs=10):\r\n        """Adapt model from source domain to robotic target domain"""\r\n\r\n        for epoch in range(num_epochs):\r\n            # Mix source and target data\r\n            source_loader = self.create_balanced_loader(\r\n                self.source_dataset,\r\n                batch_size=32,\r\n                mix_ratio=0.7  # 70% source, 30% target\r\n            )\r\n\r\n            target_loader = torch.utils.data.DataLoader(\r\n                self.target_dataset,\r\n                batch_size=32,\r\n                shuffle=True\r\n            )\r\n\r\n            # Train with domain adaptation loss\r\n            for source_batch, target_batch in zip(source_loader, target_loader):\r\n                self.train_step_with_domain_adaptation(\r\n                    source_batch,\r\n                    target_batch,\r\n                    epoch\r\n                )\r\n\r\n    def train_step_with_domain_adaptation(self, source_batch, target_batch, epoch):\r\n        """Training step with domain adaptation"""\r\n        # Standard training on source data\r\n        source_loss = self.compute_standard_loss(source_batch)\r\n\r\n        # Domain adaptation on target data\r\n        target_loss = self.compute_domain_adaptation_loss(target_batch)\r\n\r\n        # Weighted combination\r\n        alpha = min(1.0, epoch / 5)  # Gradually increase target loss weight\r\n        total_loss = (1 - alpha) * source_loss + alpha * target_loss\r\n\r\n        # Backward pass\r\n        total_loss.backward()\r\n        self.optimizer.step()\n'})}),"\n",(0,i.jsx)(n.h2,{id:"summary",children:"Summary"}),"\n",(0,i.jsx)(n.p,{children:"Vision-Language foundation models form the critical foundation for modern VLA robotic systems. These models enable robots to understand natural language commands while perceiving their environment through visual sensors. The integration of vision and language in a shared embedding space allows for zero-shot generalization to new tasks and environments."}),"\n",(0,i.jsx)(n.p,{children:"The success of VLA systems depends on careful consideration of model architecture, training data, and real-time inference requirements. As these models continue to evolve, they promise to make robots more intuitive and capable of following complex human instructions in diverse environments."}),"\n",(0,i.jsx)(n.h2,{id:"key-takeaways",children:"Key Takeaways"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"Vision-language models combine visual perception and natural language understanding"}),"\n",(0,i.jsx)(n.li,{children:"Contrastive learning aligns image and text representations in a shared space"}),"\n",(0,i.jsx)(n.li,{children:"CLIP, BLIP, and Flamingo represent key architectures in this space"}),"\n",(0,i.jsx)(n.li,{children:"Real-time optimization is crucial for robotic applications"}),"\n",(0,i.jsx)(n.li,{children:"Domain adaptation helps bridge the gap between internet training data and robotic environments"}),"\n",(0,i.jsx)(n.li,{children:"Evaluation requires specialized metrics for multimodal understanding"}),"\n",(0,i.jsx)(n.li,{children:"VLA systems extend vision-language models to include action prediction"}),"\n"]})]})}function m(e={}){const{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}}}]);